-- Schema `app`: request claims, the permissions matrix, storage order (BACKEND_SPEC §6).
-- Generated by scripts/gen-schema.mjs from packages/domain/src/store/schema.ts and friends. Do not edit by hand:
-- change the TypeScript source and run `node scripts/gen-schema.mjs`.

create extension if not exists pgcrypto with schema extensions;
create extension if not exists pg_trgm with schema extensions;

create schema if not exists app;
revoke all on schema app from public;
grant usage on schema app to authenticated, service_role;
alter default privileges in schema app revoke execute on functions from public;

-- Claims of the current request: the API sets them per transaction with
--   set local role authenticated; select set_config('request.jwt.claims', '<json>', true);
-- Roles and bindings come only from app_metadata (set by the API with the service role).
create or replace function app.claims() returns jsonb
  language sql stable security definer set search_path = ''
as $$ select coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb) $$;
comment on function app.claims() is 'Claims of the current request (request.jwt.claims).';

create or replace function app.uid() returns uuid
  language sql stable security definer set search_path = ''
as $$ select nullif(app.claims() ->> 'sub', '')::uuid $$;
comment on function app.uid() is 'Id of the signed-in user (JWT sub).';

create or replace function app.role() returns text
  language sql stable security definer set search_path = ''
as $$ select nullif(app.claims() -> 'app_metadata' ->> 'role', '') $$;
comment on function app.role() is 'Role of the user (app_metadata.role).';

create or replace function app.company_id() returns uuid
  language sql stable security definer set search_path = ''
as $$ select nullif(app.claims() -> 'app_metadata' ->> 'company_id', '')::uuid $$;
comment on function app.company_id() is 'Client company of an HR user.';

create or replace function app.clinic_id() returns uuid
  language sql stable security definer set search_path = ''
as $$ select nullif(app.claims() -> 'app_metadata' ->> 'clinic_id', '')::uuid $$;
comment on function app.clinic_id() is 'Clinic of a clinic user.';

create or replace function app.assistance_id() returns uuid
  language sql stable security definer set search_path = ''
as $$ select nullif(app.claims() -> 'app_metadata' ->> 'assistance_id', '')::uuid $$;
comment on function app.assistance_id() is 'Assistance company of its user.';

create or replace function app.insured_id() returns uuid
  language sql stable security definer set search_path = ''
as $$ select nullif(app.claims() -> 'app_metadata' ->> 'insured_id', '')::uuid $$;
comment on function app.insured_id() is 'Insured person of the app user.';

create or replace function app.aal() returns text
  language sql stable security definer set search_path = ''
as $$ select coalesce(nullif(app.claims() ->> 'aal', ''), 'aal1') $$;
comment on function app.aal() is 'Authenticator assurance level of the session (aal2 after TOTP).';

create or replace function app.is_staff() returns boolean
  language sql stable security definer set search_path = ''
as $$ select coalesce(app.role() = any(array['operator', 'underwriter', 'doctor_expert', 'accountant', 'admin', 'sales_manager', 'legal', 'claims_officer']), false) $$;
comment on function app.is_staff() is 'The user is a MIG employee.';

create or replace function app.is_clinic() returns boolean
  language sql stable security definer set search_path = ''
as $$ select coalesce(app.role() = any(array['clinic_registrar', 'clinic_admin']), false) $$;
comment on function app.is_clinic() is 'The user works for a clinic.';

create or replace function app.is_assist() returns boolean
  language sql stable security definer set search_path = ''
as $$ select coalesce(app.role() = any(array['asst_operator', 'asst_doctor', 'asst_billing', 'asst_admin']), false) $$;
comment on function app.is_assist() is 'The user works for an assistance company.';

create or replace function app.needs_aal2() returns boolean
  language sql stable security definer set search_path = ''
as $$ select app.is_staff() or app.is_clinic() or app.is_assist() $$;
comment on function app.needs_aal2() is 'MIG staff, clinics and assistance companies see data only after the second factor.';

create or replace function app.active() returns boolean
  language sql stable security definer set search_path = ''
as $$ select app.uid() is not null and app.role() is not null and (not app.needs_aal2() or app.aal() = 'aal2') $$;
comment on function app.active() is 'A signed-in user with a role (and aal2 where required): every policy starts with it.';

create or replace function app.tz() returns text language sql immutable set search_path = '' as $$ select 'Asia/Tashkent'::text $$;
comment on function app.tz() is 'Time zone of business dates.';

-- The permissions matrix (packages/domain/src/auth/permissions.ts): one row per action and role.
create table app.permissions (
  action text not null,
  role text not null,
  rule jsonb not null,
  primary key (action, role)
);
comment on table app.permissions is 'Generated from PERMISSIONS: rule is true/false or a scoped rule (own, masked, via_visit, …).';
revoke all on app.permissions from public;
grant select on app.permissions to authenticated, service_role;

create or replace function app.rule(action text) returns jsonb
  language sql stable security definer set search_path = ''
as $$ select p.rule from app.permissions p where p.action = $1 and p.role = app.role() $$;
comment on function app.rule(action text) is 'Rule of the matrix for the current role.';

create or replace function app.can(action text) returns boolean
  language sql stable security definer set search_path = ''
as $$ select coalesce((select p.rule <> 'false'::jsonb from app.permissions p where p.action = $1 and p.role = app.role()), false) $$;
comment on function app.can(action text) is 'The current role may do the action at all (its rule is not false); scopes are row predicates of the policies.';

create or replace function app.can_any(actions text[]) returns boolean
  language sql stable security definer set search_path = ''
as $$ select exists (select 1 from app.permissions p where p.action = any($1) and p.role = app.role() and p.rule <> 'false'::jsonb) $$;
comment on function app.can_any(actions text[]) is 'app.can() of any of the actions.';


-- Storage order of every table: appended rows get increasing positions, rows inserted «at start»
-- (newest-first lists) get -nextval(), i.e. decreasing negative positions. Lists order by _pos.
create sequence app.pos_seq;
grant usage on sequence app.pos_seq to authenticated, service_role;

-- Service columns: _created_at/_updated_at are kept by the database, _created_by is the signed-in user.
create or replace function app.stamp() returns trigger
  language plpgsql security definer set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new._created_at := now();
    new._updated_at := now();
    if app.uid() is not null then
      new._created_by := app.uid();
    end if;
  else
    new._created_at := old._created_at;
    new._created_by := old._created_by;
    new._updated_at := now();
  end if;
  return new;
end $$;

revoke execute on all functions in schema app from public;
grant execute on all functions in schema app to authenticated, service_role;
